#include "geom/geom.hpp"
#include "geom/detail.hpp"
namespace geom {
double area_rect(double w, double h) { return w * h; }
double area_circle(double r) { return detail::pi() * r * r; }
}

files.src/poly.cpp:
#include "geom/poly.hpp"
#include "geom/detail.hpp"
#include <cmath>
namespace geom {
double perimeter(const std::vector<double>& sides) {
    double s = 0.0;
    for (double x : sides) s += x;
    return s;
}
double regular_area(int n, double side) {
    if (n < 3) return 0.0;
    const double half = 180.0 / static_cast<double>(n);
    return static_cast<double>(n) * side * side / (4.0 * std::tan(half));
}
}

