#include "geom/geom.hpp"
#include "geom/poly.hpp"
#include <cstdio>
int main() {
    std::printf("rect=%.3f circle=%.3f perim=%.3f hex=%.3f\n",
                geom::area_rect(3.0, 4.0), geom::area_circle(2.0),
                geom::perimeter({2.0, 3.0, 4.0}), geom::regular_area(6, 3.0));
    return 0;
}

